CREATE TABLE IF NOT EXISTS events (id INTEGER PRIMARY KEY CHECK(id=1), title TEXT NOT NULL, date TEXT NOT NULL, time TEXT NOT NULL, place TEXT NOT NULL, activity TEXT NOT NULL, deadline TEXT NOT NULL, rest_from TEXT NOT NULL, active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS invitees (name TEXT PRIMARY KEY, invite_token_hash TEXT UNIQUE);
CREATE TABLE IF NOT EXISTS rsvps (name TEXT PRIMARY KEY REFERENCES invitees(name) ON UPDATE CASCADE, answer TEXT NOT NULL CHECK(answer IN ('yes','no')), message TEXT NOT NULL DEFAULT '', updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS login_attempts (key TEXT PRIMARY KEY, count INTEGER NOT NULL, reset_at INTEGER NOT NULL);
